// Unit tests for the public Claude plugin: the repo-root `.claude-plugin/plugin.json` (shipped in the npm
// package) and `.claude-plugin/marketplace.json` (`/plugin marketplace add <SUMMIT_REPO>`). Both are
// generated by `npm run build`; CI fails when the committed copies are stale (`npm run check:generated`).
import fs from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'

import { SUMMIT_NAME, SUMMIT_REPO } from '../../src/core/schemas.js'
import { SUMMIT_VERSION } from '../../src/core/version.js'
import { devPluginLaunch, npmPluginLaunch } from '../../src/install/launch.js'
import {
    PUBLIC_PLUGIN_SKILLS,
    renderClaudePlugin,
    renderCommands,
    renderMarketplace,
    renderPublicMarketplace,
    renderPublicPlugin,
} from '../../src/install/render.js'
import { REPO, sourceFiles } from '../helpers/env.js'

type Pkg = { files: string[]; repository: { url: string } }
type Hook = { type: string; command: string; args: string[] }
type HookMap = Record<string, { hooks: Hook[] }[]>

const PUBLIC_CLI = '${CLAUDE_PLUGIN_ROOT}/dist/cli.js'
const pkg = JSON.parse(fs.readFileSync(path.join(REPO, 'package.json'), 'utf8')) as Pkg
const manifest = JSON.parse(renderPublicPlugin(npmPluginLaunch()).content)

// Purpose: a dev-plugin file's JSON with the dev CLI path swapped for the public one.
function devJson(rel: string): Record<string, unknown> {
    const dev = devPluginLaunch().cli
    const file = renderClaudePlugin(devPluginLaunch()).find((f) => f.rel === rel)!
    return JSON.parse(file.content.split(dev).join(PUBLIC_CLI))
}

describe('public Claude plugin', () => {
    it('SUMMIT_REPO is the owner/repo of package.json repository.url', () => {
        expect(/github\.com\/([^/]+\/[^/.]+)/.exec(pkg.repository.url)?.[1]).toBe(SUMMIT_REPO)
    })

    it('has the same hooks and MCP server as the dev plugin, only the CLI path differs', () => {
        expect(manifest.hooks).toEqual(devJson('hooks/hooks.json').hooks)
        expect(manifest.mcpServers).toEqual(devJson('.mcp.json').mcpServers)
        expect(manifest).toMatchObject({ name: SUMMIT_NAME, version: SUMMIT_VERSION, skills: PUBLIC_PLUGIN_SKILLS })
    })

    it('starts the MCP server and every hook as node + ${CLAUDE_PLUGIN_ROOT}/dist/cli.js (exec form)', () => {
        expect(manifest.mcpServers[SUMMIT_NAME]).toEqual({
            command: 'node',
            args: [PUBLIC_CLI, 'mcp', '--harness', 'claude'],
        })
        const hooks = Object.values(manifest.hooks as HookMap).flatMap((m) => m.flatMap((e) => e.hooks))
        expect(hooks).toHaveLength(3)
        for (const h of hooks) expect([h.type, h.command, h.args[0]]).toEqual(['command', 'node', PUBLIC_CLI])
    })

    it('points `skills` at the generated Claude skills, which the npm package ships', () => {
        for (const f of renderCommands('claude')) {
            expect(fs.existsSync(path.join(REPO, PUBLIC_PLUGIN_SKILLS, f.rel.replace(/^skills\//, '')))).toBe(true)
        }
        expect(pkg.files).toEqual(
            expect.arrayContaining(['dist/cli.js', '.claude-plugin/plugin.json', 'plugins/claude/skills']),
        )
    })

    it('lists the npm package of this version in the public marketplace; the install marketplace is unchanged', () => {
        expect(JSON.parse(renderPublicMarketplace().content).plugins[0].source).toEqual({
            source: 'npm',
            package: SUMMIT_NAME,
            version: SUMMIT_VERSION,
        })
        expect(JSON.parse(renderMarketplace().content).plugins).toEqual([
            { name: SUMMIT_NAME, source: './claude', description: 'harness-summit for Claude Code' },
        ])
    })

    it('carries a marketplace description and a plugin author (`claude plugin validate` warns without them)', () => {
        const market = JSON.parse(renderPublicMarketplace().content)
        expect(market.description).toEqual(expect.any(String))
        expect(market.description.length).toBeGreaterThan(0)
        expect(manifest.author).toEqual({ name: SUMMIT_REPO.split('/')[0] })
        expect(manifest.author).toEqual({ name: 'anthonyleung-dev' })
        // install's local marketplace keeps its earlier bytes: no description key.
        expect(JSON.parse(renderMarketplace().content).description).toBeUndefined()
    })

    it('the repo-root files equal their renderers, and the repo root has no .mcp.json', () => {
        for (const f of [renderPublicPlugin(npmPluginLaunch()), renderPublicMarketplace()]) {
            expect(fs.readFileSync(path.join(REPO, f.rel), 'utf8'), f.rel).toBe(f.content)
        }
        expect(fs.existsSync(path.join(REPO, '.mcp.json'))).toBe(false)
    })

    it('render.ts builds the product name from SUMMIT_NAME, never types it out', () => {
        const text = fs.readFileSync(path.join(REPO, 'src', 'install', 'render.ts'), 'utf8')
        expect(text).toContain('SUMMIT_NAME')
        expect(text.includes(SUMMIT_NAME)).toBe(false)
    })

    it('names ${CLAUDE_PLUGIN_ROOT}/ only in src/install/launch.ts (one door for plugin launch paths)', () => {
        const src = path.join(REPO, 'src')
        const hits = sourceFiles(src).filter((f) => fs.readFileSync(f, 'utf8').includes('${CLAUDE_PLUGIN_ROOT}/'))
        expect(hits.map((f) => path.relative(src, f).split(path.sep).join('/'))).toEqual(['install/launch.ts'])
    })
})
